import numpy as np

from mcf.research.arena.indicators import compute

SIDE = 'short'
GEOM = 'hold'
WINDOW = (1030, 1200)          # bar close lo <= tod <= hi (inclusive, as the YAML window)
MIN_ADV = 95000000.0
CONTEXT = ['qqq_fo']              # lab context columns (config `context:`), point-in-time per 5-minute bar
CONDS = [
    ('dist_pdh_atr', '<=', -0.65),
    ('new_hod', '==', 1.0),
    ('qqq_fo', '<', -0.6),
]
LAYERS = ['dist_pdh_atr <= -0.65', 'new_hod == 1', 'qqq_fo < -0.6', 'window 1030-1200']


def mask(df) -> np.ndarray:
    x = compute(df, names=['dist_pdh_atr', 'new_hod'], context=False)
    tod = df["tod"].to_numpy(dtype=float)
    m = (tod >= WINDOW[0]) & (tod <= WINDOW[1])
    with np.errstate(invalid="ignore"):
        for nm, op, v in CONDS:
            if nm in CONTEXT:
                a = df[nm].to_numpy(dtype=float) if nm in df.columns else np.full(len(df), np.nan)
            else:
                a = x[nm].to_numpy(dtype=np.float32).astype(float)
                v = float(np.float32(v))
            if op == "<=":
                m &= a <= v
            elif op == "<":
                m &= a < v
            elif op == ">=":
                m &= a >= v
            elif op == ">":
                m &= a > v
            else:
                m &= a == v
    return np.asarray(m, dtype=bool)
